import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/widgets.dart';

class AppBranding {
  static const String logoPath = 'assets/images/bhoomi_logo.png';
  static const String emblemPath = 'assets/images/bhoomi_emblem.png';

  static final Uint8List logoBytes = base64Decode(
    '',
  );

  static final Uint8List emblemBytes = base64Decode(
    '',
  );

  static Widget logoImage({double? height, double? width, BoxFit fit = BoxFit.contain}) {
    return Image.memory(
      logoBytes,
      height: height,
      width: width,
      fit: fit,
      errorBuilder: (_, __, ___) => Image.asset(
        logoPath,
        height: height,
        width: width,
        fit: fit,
      ),
    );
  }

  static Widget emblemImage({double? height, double? width, BoxFit fit = BoxFit.contain}) {
    return Image.memory(
      emblemBytes,
      height: height,
      width: width,
      fit: fit,
      errorBuilder: (_, __, ___) => Image.asset(
        emblemPath,
        height: height,
        width: width,
        fit: fit,
      ),
    );
  }

  static const String heroPath = 'assets/illustrations/farmer_hero.jpg';

  static final Uint8List heroBytes = base64Decode(
    '',
  );

  static Widget heroIllustration({double? height, double? width, BoxFit fit = BoxFit.cover}) {
    return Image.memory(
      heroBytes,
      height: height,
      width: width,
      fit: fit,
      errorBuilder: (_, __, ___) => Image.asset(
        heroPath,
        height: height,
        width: width,
        fit: fit,
      ),
    );
  }
}
